export function copiedInputs(root: string, realInputs: ReadonlyMap<string, string>): void {
  for (const [file, source] of realInputs) {
    mkdirSync(dirname(join(root, file)), { recursive: true });
    writeFileSync(join(root, file), source);
  }
  for (const file of CLI_MODULES) {
    mkdirSync(dirname(join(root, file)), { recursive: true });
    writeFileSync(join(root, file), readFileSync(join(import.meta.dir, "../..", file)));
  }
}
